import moment from 'moment';

export const formatDateTime = (dateTime: string, defaultValue = '-') => {
  return (
    moment(dateTime)
      .format('HH:mm DD/MM/YYYY')
      .replace(`/${new Date().getFullYear()}`, '') ||
    defaultValue ||
    dateTime ||
    ''
  ).replace(`/${new Date().getFullYear()}`, '');
};
